/* =========================================================
   Puff · 长夜＆机械之心 × 樱花晨光玻璃（极高透版）
   ➠如果有灰雾，退出来重进就好了
   原因：软件自带的渲染引擎（WebView）卡了，没把透明图层刷新出来，退出重进相当于强制清空了缓存重新画，所以就正常了。
========================================================= */

/* 1. 全局变量与方角设定 */
.off-app {
  --off-list-radius: 0px;
  --off-list-ava-size: 52px;
  --off-pink: #efb8cb;
}

/* 强制所有元素变方角 */
.off-app .off-list,
.off-app .off-list-ava,
.off-app.off-app-session .off-passage-sheet,
.off-app .off-compose-bar,
.off-app .off-thinking-chip {
  border-radius: 0 !important;
}

/* 2. 核心注入：全局背景图 */
.off-app,
.off-app .off-stage,
.off-app.off-app-session .off-stage,
.off-app.off-app-session .off-stage.has-bg {
  background-color: transparent !important;
  background-image: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141b1ab1.webp') !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
}
.off-app .off-stage, 
.off-app .off-prose-scroll {
  background-color: transparent !important;
}

/* =========================================================
   👇【核心修复】全局文字强制深色 + 强白边护体
   ========================================================= */
.off-app, 
.off-app div, .off-app span, .off-app p, .off-app a, .off-app label, .off-app li, .off-app input, .off-app select {
  color: #333333 !important;
  -webkit-text-fill-color: #333333 !important;
  text-shadow: 0 1px 3px rgba(255, 255, 255, 1), 0 0 5px rgba(255, 255, 255, 0.8) !important; 
}

/* 全局按钮白底黑字 */
.off-app button, .off-app [class*="btn"], .off-app [class*="button"], .off-app .off-list-btn {
  background: rgba(255, 255, 255, 0.5) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
  color: #333333 !important;
  -webkit-text-fill-color: #333333 !important;
  text-shadow: none !important;
}

/* 👇【新增】：强制把顶栏所有图标/返回键的框和底色褪掉 */
.off-app .off-stage-head button,
.off-app .off-stage-head [class*="btn"],
.off-app .off-stage-head [class*="back"],
.off-app [class*="head"] [class*="back"],
.off-app [class*="nav"] button {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* =========================================================
   3. 共处列表页（高透）
   ========================================================= */
.off-app:not(.off-app-session) .off-list {
  background: rgba(255, 255, 255, 0.3) !important; 
  border: 1px solid rgba(255, 255, 255, 0.8) !important;
}

/* 👇 核心修复：只给“单聊/群共处”做框，单独做字色 */
.off-app:not(.off-app-session) .off-stage-head [class*="filter"],
.off-app:not(.off-app-session) .off-stage-head [class*="tab"],
.off-app:not(.off-app-session) .off-stage-head [class*="switch"] {
  background: transparent !important;
  border: none !important;
}
.off-app:not(.off-app-session) .off-stage-head [class*="filter"] button,
.off-app:not(.off-app-session) .off-stage-head [class*="tab"] button,
.off-app:not(.off-app-session) .off-stage-head [class*="switch"] button {
  background: rgba(255, 255, 255, 0.3) !important;
  border: 1px solid rgba(255, 255, 255, 0.7) !important; 
  color: #666666 !important; -webkit-text-fill-color: #666666 !important;
  text-shadow: none !important;
}
.off-app:not(.off-app-session) .off-stage-head [class*="filter"] button.on,
.off-app:not(.off-app-session) .off-stage-head [class*="tab"] button.on,
.off-app:not(.off-app-session) .off-stage-head [class*="switch"] button.on {
  background: rgba(255, 255, 255, 0.85) !important;
  border: 1px solid #ec7ca0 !important; 
  color: #ec7ca0 !important; -webkit-text-fill-color: #ec7ca0 !important;
}

/* =========================================================
   4. 聊天顶栏 + 爱心心电图
   ========================================================= */
.off-app.off-app-session .off-stage-head {
  background: transparent !important; 
  border-bottom: none !important;
  position: relative !important;
  overflow: visible !important;
  z-index: 10 !important;
}
.off-app.off-app-session .off-stage-head::after {
  content: "" !important; position: absolute !important;
  bottom: -16px !important; left: 0 !important; right: 0 !important; height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ec7ca0" stroke-width="1.5" opacity="0.9"/></svg>') !important;
  background-size: 120px 16px !important; background-repeat: repeat-x !important;
  animation: ecg-flow 3s linear infinite !important; z-index: 99 !important;
}
.off-app.off-app-session .off-stage-head::before {
  content: '♥' !important; position: absolute !important;
  bottom: -23px !important; left: 10% !important; font-size: 16px !important;
  color: #ec7ca0 !important; text-shadow: 0 0 6px rgba(255, 255, 255, 0.9) !important; 
  z-index: 999 !important; pointer-events: none !important;
  animation: heart-walk 4s ease-in-out infinite alternate !important;
}

/* =========================================================
   5. 消息卡片与对话（极高透）
   ========================================================= */
.off-app.off-app-session .off-passage-sheet {
  background: rgba(255, 255, 255, 0.15) !important; 
  border: 1px solid rgba(255, 255, 255, 0.4) !important; 
  box-shadow: none !important;
}

.off-app.off-app-session .off-prose-dial,
.off-app.off-app-session [class*="dial"],
.off-app .off-compose-quote,
.off-app .off-passage-quote,
.off-app [class*="quote"] {
  display: inline !important; 
  box-decoration-break: clone !important; -webkit-box-decoration-break: clone !important;
  background: rgba(255, 255, 255, 0.25) !important; 
  border-radius: 0 !important; padding: 1px 8px !important; margin: 0 4px !important; 
  border: 1px solid rgba(255, 255, 255, 0.6) !important; 
  box-shadow: none !important; 
}

/* =========================================================
   6. 悬浮菜单与底栏（高透）
   ========================================================= */
.off-app [class*="menu"], .off-app [class*="popover"], .off-app [class*="popup"], .off-app [class*="dialog"] {
  background: rgba(255, 255, 255, 0.85) !important; 
  backdrop-filter: blur(20px) !important;
  border: 1.5px solid #ffffff !important;
  border-radius: 0 !important; 
  box-shadow: 0 12px 36px rgba(236, 124, 160, 0.2) !important;
}
.off-app [class*="menu"] button, .off-app [class*="menu"] svg { fill: #333333 !important; }
.off-app [class*="delete"] *, .off-app [class*="danger"] * { color: #ec7ca0 !important; fill: #ec7ca0 !important; }

.off-app.off-app-session .off-stage-dock {
  background: rgba(255, 255, 255, 0.35) !important; 
  border-top: none !important;
  position: relative !important; overflow: visible !important; z-index: 10 !important; padding-top: 20px !important;
}
.off-app.off-app-session .off-stage-dock::before {
  content: "" !important; position: absolute !important;
  top: -16px !important; left: 0 !important; right: 0 !important; height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ec7ca0" stroke-width="1.5" opacity="0.9"/></svg>') !important;
  background-size: 120px 16px !important; background-repeat: repeat-x !important;
  animation: ecg-flow-reverse 3s linear infinite !important; z-index: 99 !important;
}

.off-app .off-compose-bar {
  background: rgba(255, 255, 255, 0.4) !important; 
  border: 1px solid rgba(255, 255, 255, 0.8) !important;
}
.off-app .off-compose-send, .off-app .off-compose-send * {
  color: #ec7ca0 !important; -webkit-text-fill-color: #ec7ca0 !important; fill: #ec7ca0 !important; background: transparent !important;
}

/* 7. 日间专属：粉晶果冻呼吸头像 */
.off-app .off-list-ava, .off-app .chat-ava-list {
  border-radius: 14px !important; border: 1.5px solid rgba(255, 255, 255, 0.95) !important; 
  background: linear-gradient(135deg, #fff5f8, #fbcbdf) !important; padding: 2px !important;
  box-shadow: inset 0 0 6px rgba(255, 255, 255, 1), 0 0 12px rgba(236, 124, 160, 0.4) !important; 
  animation: jelly-glow 3s ease-in-out infinite alternate !important; 
}
.off-app .off-list-ava img, .off-app .chat-ava-list img { border-radius: 11px !important; object-fit: cover !important; }

/* 动画 */
@keyframes ecg-flow { 0% { background-position: 0 0; } 100% { background-position: -120px 0; } }
@keyframes ecg-flow-reverse { 0% { background-position: 0 0; } 100% { background-position: 120px 0; } }
@keyframes heart-walk {
  0% { left: 4%; transform: translateY(0) scale(1); } 30% { transform: translateY(-4px) scale(1.15); } 
  60% { transform: translateY(0) scale(1); } 80% { transform: translateY(-4px) scale(1.15); } 
  100% { left: 96%; transform: translateY(0) scale(1); }
}
@keyframes jelly-glow {
  0% { box-shadow: inset 0 0 6px rgba(255, 255, 255, 1), 0 0 4px rgba(236, 124, 160, 0.2); }
  100% { box-shadow: inset 0 0 8px rgba(255, 255, 255, 1), 0 0 16px rgba(236, 124, 160, 0.6); }
}
